"""DTC Playbook pages. Sources checked 2026-10-17."""
SRC={
'rc4064':('CRA Guide RC4064, Disability-Related Information 2025','https://www.canada.ca/en/revenue-agency/services/forms-publications/publications/rc4064/disability-related-information.html'),
'howapply':('CRA: How to apply for the DTC','https://www.canada.ca/en/revenue-agency/services/tax/individuals/segments/tax-credits-deductions-persons-disabilities/disability-tax-credit/how-apply-dtc.html'),
'dtc':('CRA: Disability tax credit','https://www.canada.ca/en/revenue-agency/services/tax/individuals/segments/tax-credits-deductions-persons-disabilities/disability-tax-credit.html'),
'mental':('CRA: Mental functions eligibility','https://www.canada.ca/en/revenue-agency/services/tax/individuals/segments/tax-credits-deductions-persons-disabilities/disability-tax-credit/eligible-dtc/mental-functions.html'),
'speaking':('CRA: Speaking eligibility','https://www.canada.ca/en/revenue-agency/services/tax/individuals/segments/tax-credits-deductions-persons-disabilities/disability-tax-credit/eligible-dtc/speaking.html'),
'folio':('CRA Income Tax Folio S1-F1-C2, Disability Tax Credit','https://www.canada.ca/en/revenue-agency/services/tax/technical-information/income-tax/income-tax-folios-index/series-1-individuals/folio-1-health-medical/income-tax-folio-s1-f1-c2-disability-tax-credit.html'),
't2201':('Form T2201, Disability Tax Credit Certificate (PDF)','https://www.canada.ca/content/dam/cra-arc/formspubs/pbg/t2201/t2201-23e.pdf'),
'claiming':('CRA: Claiming the DTC (past years)','https://www.canada.ca/en/revenue-agency/services/tax/individuals/segments/tax-credits-deductions-persons-disabilities/disability-tax-credit/claiming-dtc.html'),
'change':('Canada.ca: Changing a tax return','https://www.canada.ca/en/services/taxes/income-tax/personal-income-tax/after-you-file/change-return.html'),
'cdb':('CRA: Child disability benefit','https://www.canada.ca/en/revenue-agency/services/child-family-benefits/child-disability-benefit.html'),
'rdspcf':('CRA: Canada disability savings grant and bond (carry forward)','https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/registered-disability-savings-plan-rdsp/canada-disability-savings-grant-canada-disability-savings-bond.html'),
'rdsphow':('Canada.ca: How much you could get in grants and bonds','https://www.canada.ca/en/employment-social-development/programs/disability/savings/how-much.html'),
'rc161':('CRA Form RC161, Authorization for Parliamentarians','https://www.canada.ca/en/revenue-agency/services/forms-publications/forms/rc161.html'),
'findmp':('House of Commons: Find Members of Parliament (search by postal code)','https://www.ourcommons.ca/members/en'),
'chh':('House of Commons: Chilliwack—Hope constituency','https://www.ourcommons.ca/Members/en/constituencies/chilliwack-hope(1244)'),
'dabcfund':('Disability Alliance BC: DTC Medical Fees Fund','https://disabilityalliancebc.org/direct-service/help-with-the-rdsp-and-dtc/dtc-medical-fees-fund/'),
'dabc':('Disability Alliance BC: Help with the RDSP and DTC','https://disabilityalliancebc.org/direct-service/help-with-the-rdsp-and-dtc/'),
'dobc':('Doctors of BC: Out-of-pocket (uninsured) fees','https://www.doctorsofbc.ca/sites/default/files/uninsured_services.pdf'),
'medexp':('CRA: Lines 33099 and 33199, eligible medical expenses','https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/lines-33099-33199-eligible-medical-expenses-you-claim-on-your-tax-return.html'),
}
def build(page,E,SITE,SHARE,mlform,NL_URL):
    def cite(*keys): return '<p class="cite">Source: '+' · '.join(f'<a href="{SRC[k][1]}" rel="noopener">{E(SRC[k][0])}</a>' for k in keys)+'</p>'
    MEANS={'A marked restriction':'Even with therapy, devices and medicine, your child can’t do one of these things, or it takes them a very long time. And this is true almost all the time.',
     'An individual':'“All the time” means your child has this problem at least 90% of the time.',
     'Generally, that difference':'“A very long time” usually means at least 3 times longer than other kids the same age.',
     'An impairment is prolonged':'The disability has lasted, or is expected to last, at least 12 months in a row.',
     'Eligibility for the DTC':'A diagnosis alone is not enough. The CRA looks at how the disability affects your child’s daily life.',
     'You are unable to speak':'Someone who knows your child well can’t understand them in a quiet room, or it takes your child 3 times longer than other kids their age to be understood.',
     'You must rely on other':'If your child uses sign language, pictures, a symbol board or an AAC app to talk, they may qualify.',
     'adaptive functioning':'These are the thinking skills used every day: paying attention, remembering, solving problems, staying calm, and understanding what others say or show.',
     'You are unable to express':'Your child can’t tell others what they need, or can’t tell what will happen because of what they do.',
     'You cannot make a common':'Your child can’t do a simple task, like buying food, without help.'}
    def q(text,key):
        m=next((v for k,v in MEANS.items() if text.startswith(k)),None)
        return f'<blockquote class="cra"><p>“{E(text)}”</p><footer>— <a href="{SRC[key][1]}" rel="noopener">{E(SRC[key][0])}</a></footer></blockquote>'+(f'<p class="means"><strong>What this means:</strong> {E(m)}</p>' if m else '')
    nav_items=[('index.html','Start here'),('wording.html','Describe daily life'),('fees.html','Doctor fees'),('mp-help.html','Get your MP to help'),('back-pay.html','Back pay')]
    def subnav(cur): return '<nav class="subnav" aria-label="DTC Playbook">'+''.join(f'<a href="{h}"'+(' aria-current="page"' if h==cur else '')+f'>{t}</a>' for h,t in nav_items)+'</nav>'
    def head(cur,h1,sub): return f'<p class="crumb"><a href="../index.html">Funding Guide</a> › <a href="index.html">DTC Playbook</a></p>{subnav(cur)}<h1>{h1}</h1><p class="sub left">{sub}</p>'
    pr='<p><button type="button" class="pill ghost" onclick="window.print()">Print this page</button></p>'
    share=lambda path,text: SHARE.format(url=f'{SITE}/funding/dtc/{path}',text=text)
    srcs=lambda *k: '<h2>Official sources</h2><ul class="srcs">'+''.join(f'<li><a href="{SRC[x][1]}" rel="noopener">{E(SRC[x][0])}</a></li>' for x in k)+'</ul><p class="note">Checked 2026-10-17. Rules change, so always confirm on the official page. Not legal or tax advice.</p>'
    out=[]
    # 1. overview
    steps=[("Check the 3 tests","The CRA (Canada Revenue Agency) looks at how the disability affects daily life, not the diagnosis. It must be severe (CRA calls this a “marked restriction”). It must happen almost all the time (about 90% of the time or more). And it must last a long time (12 months or more)."),
           ("Pick the right health professional","CRA calls them a “medical practitioner.” A doctor or nurse practitioner can sign for any category. A psychologist can sign for thinking and behaviour (CRA calls this “mental functions”). A speech-language pathologist can sign for speaking. An occupational therapist can sign for walking, feeding and dressing."),
           ("Fill out Part A (you)","Do it online in your CRA account (Benefits and credits › Apply for DTC), by phone at 1-800-959-8281, or on the paper T2201 form. Tick the box that asks CRA to fix your past tax returns. That’s how you get back pay."),
           ("Give the health professional your reference number","If you apply online, Part A gives you a reference number. It works for up to 12 months. Your health professional uses it to fill in Part B online. It goes to CRA by itself."),
           ("Help them describe daily life","Bring a one-page sheet with real examples from your child’s day. Use our Describe daily life page."),
           ("Wait for CRA’s letter","CRA mails you a yes or no (called a “notice of determination”). If it’s yes, CRA fixes the past tax returns you asked for. If you get the Canada Child Benefit, the Child Disability Benefit starts by itself."),
           ("If the answer is no","You can ask your tax centre to look again and send new medical information. Or you can file a formal objection (an official request to change the decision) within 90 days of the letter.")]
    b=head('index.html','The DTC Playbook.','The Disability Tax Credit (DTC) opens the door to the Child Disability Benefit, RDSP grants and bonds, and BC’s new disability supplement. Here’s how to apply, step by step.')
    b+='<div class="sumcard"><div><strong>Who fills what</strong><span><b>Part A:</b> you. A parent signs for a child under 18. <b>Part B:</b> a health professional, like a doctor. Never the parent.</span></div><div><strong>Digital or paper</strong><span>Use the same way for both parts. Online: do Part A in your CRA account or by phone. Then Part B is done online with your reference number. Paper: mail both parts together. Since July 14, you can’t send DTC forms through “Submit documents.”</span></div><div><strong>Cost to apply</strong><span>CRA doesn’t charge anything. Some doctors charge a fee. <a href="fees.html">See doctor fees</a></span></div></div>'
    b+='<h2>Step by step</h2><ol class="steps big">'+''.join(f'<li><strong>{E(t)}</strong><br>{E(d)}</li>' for t,d in steps)+'</ol>'+cite('howapply','rc4064')
    b+='<div class="cards3 play">'+''.join(f'<a class="tile" href="{h}"><h2>{t}</h2><span>Open ›</span></a>' for h,t in nav_items[1:])+'</div>'
    b+=share('index.html','The Disability Tax Credit is the key to the Child Disability Benefit and RDSP. Here is a free step-by-step playbook for parents:')+srcs('howapply','rc4064','dtc','t2201')
    ld=[{"@context":"https://schema.org","@type":"HowTo","name":"How to apply for the Disability Tax Credit for your child","totalTime":"PT30M","supply":[{"@type":"HowToSupply","name":"Form T2201 or CRA account"},{"@type":"HowToSupply","name":"Child's SIN and date of birth"}],"step":[{"@type":"HowToStep","position":i+1,"name":t,"text":d} for i,(t,d) in enumerate(steps)]}]
    page('funding/dtc/index.html','DTC Playbook: how to apply for the Disability Tax Credit for your child','Step-by-step guide to the Disability Tax Credit (Form T2201) for parents: who fills each part, digital vs paper, the 90% and 12-month tests, and what happens next.',b,ld,og='og-dtc.png')
    # 2. wording
    b=head('wording.html','Help your doctor describe daily life.','CRA decides based on what your doctor or other health professional writes. Your job is to give them true, clear examples of how the disability affects your child’s day. Describe what happens, not just the diagnosis.')
    b+='<div class="callout"><strong>Honest is strongest.</strong> Never make things sound worse than they are, and never ask anyone else to. The health professional decides for themselves, and CRA may call them. Clear, true examples help them describe your child well.</div>'
    b+='<h2>The words CRA uses</h2>'
    b+=q('A marked restriction means that, even with appropriate therapy, devices, and medication, the individual is unable or takes an inordinate amount of time to perform activities or functions in one of the listed categories, and this is the case all or substantially all of the time.','rc4064')
    b+=q("An individual's limitations are generally considered to exist all or substantially all of the time if the individual's impairment limits their ability to perform activities or functions in a category at least 90% of the time.",'rc4064')
    b+=q('Generally, that difference must be at least 3 times longer than is required by persons of similar age who do not have an impairment in the particular category.','rc4064')
    b+=q('An impairment is prolonged if it has lasted for a continuous period of at least 12 months or it is expected to last for a continuous period of at least 12 months.','rc4064')
    b+=q('Eligibility for the DTC is based on the effects of an impairment, not a diagnosis or the presence of a medical condition.','mental')
    b+='<h2>Speaking</h2>'+q('You are unable to speak so as to be understood by a familiar person in a quiet setting, or it takes you 3 times longer than someone of similar age who does not have the impairment (even if you use appropriate therapy, medication, and devices)','speaking')
    b+='<p>CRA’s own example of someone who may qualify:</p>'+q('You must rely on other means of communication, such as sign language or a symbol board','rc4064')+'<p>Who can sign: a doctor, nurse practitioner, or speech-language pathologist.</p>'
    b+='<h2>Thinking and behaviour (CRA calls this “mental functions necessary for everyday life”)</h2>'+q('adaptive functioning, attention, concentration, goal-setting, judgment, memory, perception of reality, problem-solving, regulation of behaviour and emotions, verbal and non-verbal comprehension','rc4064')
    b+='<p>CRA examples of who may qualify:</p>'+q('You are unable to express your needs or anticipate consequences of behaviour when interacting with others','rc4064')+q('You cannot make a common, simple transaction, such as buying food at the grocery store, without help','rc4064')+'<p>CRA’s mental functions page gives everyday examples, like “Showing awareness of danger and risks to personal safety”, “Demonstrating basic impulse control” and “Understanding and responding to non-verbal information or cues”. Who can sign: a doctor, nurse practitioner, or psychologist.</p>'+cite('mental')
    b+='<h2>Other categories</h2><p>CRA also has categories for seeing, hearing, walking, eliminating (using the toilet, bowel or bladder), feeding and dressing. There is also <strong>cumulative effect</strong> (smaller limits in 2 or more categories that add up). And there is <strong>life-sustaining therapy</strong> (care needed to stay alive or healthy, at least 2 times a week, for an average of at least 14 hours a week). For a child, time a parent spends doing the therapy can count.</p>'+cite('rc4064')
    prep=[("Child's name, age, diagnosis(es), and who diagnosed","Just for background. CRA looks at how it affects daily life."),
          ("How long these limits have lasted","The month and year they started. It must last, or be expected to last, 12 months or more."),
          ("Which categories apply","For example: speaking, thinking and behaviour (mental functions), feeding, dressing, using the toilet."),
          ("Speaking: how does your child communicate?","e.g. “Uses an AAC app or symbol board for needs; no words a familiar person can understand in a quiet room.”"),
          ("Mental functions: daily examples","e.g. “Runs toward the road with no awareness of danger, needs constant supervision outdoors.” “Can't tell us when in pain or sick.” “Meltdowns lasting 30+ minutes several times a day when routine changes.”"),
          ("How often? (out of 10 days, how many?)","CRA looks for about 90% of the time (9 out of 10 days). Be honest about good days too."),
          ("How much longer than other kids the same age?","e.g. “Dressing takes about 25 minutes with full help; a typical 7-year-old does it alone in about 5.”"),
          ("What you've tried (therapy, devices, medication)","CRA asks about limits even when your child gets this help."),
          ("Who else sees this","Teachers, speech therapist (SLP), occupational therapist (OT), behaviour consultant. Bring any reports.")]
    b+='<h2>Parent prep sheet</h2><p>Fill this in, print it, and give it to your doctor before the appointment. Write what\'s true for your child, in your own words.</p><div class="sheet"><table><caption class="sr">Parent prep sheet</caption><thead><tr><th scope="col">Question</th><th scope="col">Your notes</th></tr></thead><tbody>'+''.join(f'<tr><td><strong>{E(a)}</strong><br><small>{E(c)}</small></td><td class="blank"></td></tr>' for a,c in prep)+'</tbody></table></div>'+pr
    b+='<h2>Describe effects, not labels</h2><table><thead><tr><th scope="col">Less helpful</th><th scope="col">More helpful (if it\'s true)</th></tr></thead><tbody><tr><td>“He has autism.”</td><td>“He has no spoken words. In a quiet room, family can’t understand him without his symbol board, every day.”</td></tr><tr><td>“She has behaviour problems.”</td><td>“She bolts toward traffic and needs an adult within arm’s reach outside, every day.”</td></tr><tr><td>“He’s a picky eater.”</td><td>“He needs hand-over-hand help and about 45 minutes per meal, at almost every meal.”</td></tr></tbody></table><p class="note">These are examples of style only. Use your child\'s real situation.</p>'
    b+=share('wording.html','A plain-language prep sheet to help your doctor describe your child accurately on the Disability Tax Credit form:')+srcs('rc4064','mental','speaking','folio','t2201')
    faq=[("Can I fill out Part B myself?","No. A health professional, like a doctor, must fill in Part B. CRA says if you fill it in yourself, they won’t look at it."),("Does an autism diagnosis qualify for the DTC?","Not by itself. CRA looks at how the disability affects daily life, not the diagnosis. Your doctor describes how it affects things like speaking, or thinking and behaviour."),("What does 'all or substantially all of the time' mean?","CRA usually means at least 90% of the time. That’s about 9 days out of 10."),("Does using an AAC app or symbol board count for speaking?","CRA lists 'You must rely on other means of communication, such as sign language or a symbol board' as an example of someone who may be eligible under speaking. CRA still decides based on what the health professional writes.")]
    ld=[{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":a,"acceptedAnswer":{"@type":"Answer","text":c}} for a,c in faq]}]
    b+=''.join(f'<h2>{E(a)}</h2><p>{E(c)}</p>' for a,c in faq)
    page('funding/dtc/wording.html','DTC wording: describe your child\'s daily life using CRA\'s criteria','CRA\'s exact Disability Tax Credit terms (marked restriction, 90% of the time, 12 months, speaking, mental functions) and a printable parent prep sheet for your practitioner.',b,ld,og='og-dtc.png')
    # 3. fees
    b=head('fees.html','Doctor fees for the DTC form.','MSP (BC health insurance) doesn’t pay for filling in Part B, so many offices charge a fee. Here’s how to keep the cost down.')
    b+='<div class="sumcard"><div><strong>Ask first</strong><span>Fees are different at each office. Ask the price before the appointment. Ask if you can pay a bit at a time. Doctors of BC tells patients to ask about fees MSP doesn’t cover before getting the service.</span></div><div><strong>Typical range</strong><span>Disability Alliance BC says there are no set rules for these fees, and they “can cost people anywhere between $100-$250.”</span></div><div><strong>Claim it back</strong><span>CRA says you may be able to claim the fee as a medical expense on your taxes (lines 33099 or 33199).</span></div></div>'+cite('dabcfund','dobc','rc4064')
    b+='<h2>Ways to lower the cost</h2><ol class="steps"><li><strong>Apply to DABC\'s DTC Medical Fees Fund.</strong> Disability Alliance BC (DABC) has a fund to help people in BC pay doctor fees for the DTC form. <a href="'+SRC['dabcfund'][1]+'" rel="noopener">DTC Medical Fees Fund</a></li><li><strong>Ask a practitioner who already knows your child.</strong> CRA lets these health professionals sign for some categories: psychologists (mental functions), speech-language pathologists (speaking), occupational therapists (walking, feeding, dressing), and nurse practitioners (all categories). Some may charge less, or include it in services you already pay for. Ask.</li><li><strong>Bring your prep sheet.</strong> A clear one-pager can save the practitioner time. <a href="wording.html">Get the prep sheet</a></li><li><strong>Get free help with the application.</strong> Disability Alliance BC helps with the DTC and RDSP. <a href="'+SRC['dabc'][1]+'" rel="noopener">DABC DTC and RDSP help</a></li><li><strong>First Nations families:</strong> ask a Jordan\'s Principle Service Coordinator whether help with costs is possible for your child. <a href="../jordans-principle.html">Jordan\'s Principle</a></li></ol>'
    b+='<p class="note">We couldn\'t verify that BC\'s crisis supplement covers DTC form fees, so we don\'t list it here. Ask your ministry worker if you\'re on assistance.</p>'
    b+=share('fees.html','Doctor charging for the Disability Tax Credit form? Here is how BC parents can lower the cost:')+srcs('howapply','rc4064','dabcfund','dabc','dobc','medexp')
    page('funding/dtc/fees.html','Disability Tax Credit doctor fees in BC: what to expect and how to save','DTC form fees in BC aren\'t covered by MSP. Ask upfront, use DABC\'s DTC Medical Fees Fund, ask the right practitioner, and claim the fee as a medical expense.',b,og='og-dtc.png')
    # 4. MP help
    tmpl=('Subject: Request for help with a CRA Disability Tax Credit file\n\nDear [MP name] and constituency staff,\n\nI live in [riding] at [address, postal code]. I applied for the Disability Tax Credit for my child, [child\'s name, date of birth], on [date] by [digital form / mail]. [My reference number is ___.] It has now been [number] weeks and [describe the problem: no decision / request for information already answered / no reply to my letter].\n\nCould your office please make an inquiry with the Canada Revenue Agency about the status of this file? I have attached a signed Form RC161, Authorization for Parliamentarians, and copies of [list documents].\n\nThe best way to reach me is [phone/email]. Thank you for your help.\n\n[Your name]\n[Your SIN is on the RC161 form only, not in this email]')
    b=head('mp-help.html','Get your MP to help.','Stuck with CRA? Your MP’s local office can ask CRA about your file for free. (Your MP is your Member of Parliament, your federal representative.) CRA needs your written OK first.')
    b+='<ol class="steps big"><li><strong>Find your MP.</strong> Search by postal code on the House of Commons site. <a href="'+SRC['findmp'][1]+'" rel="noopener">Find your MP</a></li><li><strong>Sign Form RC161.</strong> This form (Authorization for Parliamentarians) lets CRA share your private file with your MP and their staff. <a href="'+SRC['rc161'][1]+'" rel="noopener">Get RC161</a></li><li><strong>Gather what to send:</strong> copy of your T2201 or reference number, the date you applied, any CRA letters, your notice of determination (if any), and a short timeline.</li><li><strong>Email or call the MP’s local office</strong> (called a constituency office). Use the template below. Many MP offices have their own consent form too; use it if they ask.</li></ol>'+cite('findmp','rc161')
    b+='<h2>Chilliwack—Hope</h2><p>The House of Commons lists the Chilliwack—Hope constituency office at 102-7388 Vedder Road, Chilliwack, BC V2R 4E4, phone 604-847-9711. <a href="'+SRC['chh'][1]+'" rel="noopener">Check the current MP and office details</a></p>'
    b+='<h2>Copy-paste email template</h2><div class="tmpl"><textarea id="mp-tmpl" rows="16" readonly aria-label="Email template">'+E(tmpl)+'</textarea><p><button type="button" class="pill" onclick="var t=document.getElementById(\'mp-tmpl\');t.select();(navigator.clipboard?navigator.clipboard.writeText(t.value):Promise.reject()).then(function(){document.getElementById(\'mp-out\').textContent=\'Copied.\'},function(){document.execCommand(\'copy\');document.getElementById(\'mp-out\').textContent=\'Copied.\'})">Copy template</button> <output id="mp-out" aria-live="polite"></output></p></div><p class="note">Never put your SIN in a regular email. It goes on the RC161 form only.</p>'
    b+=share('mp-help.html','DTC application stuck at CRA? Your MP\'s office can help. Free template for parents:')+srcs('findmp','rc161','chh','howapply')
    ld=[{"@context":"https://schema.org","@type":"HowTo","name":"Ask your MP's office to help with a CRA Disability Tax Credit file","step":[{"@type":"HowToStep","position":1,"text":"Find your MP by postal code on ourcommons.ca."},{"@type":"HowToStep","position":2,"text":"Sign CRA Form RC161, Authorization for Parliamentarians."},{"@type":"HowToStep","position":3,"text":"Gather your T2201 or reference number, dates and CRA letters."},{"@type":"HowToStep","position":4,"text":"Email or call the constituency office with a short request."}]}]
    page('funding/dtc/mp-help.html','DTC stuck at CRA? How to get your MP\'s office to help','How BC parents can ask their MP\'s constituency office to make inquiries with CRA about a Disability Tax Credit file: RC161 consent, what to send, and an email template.',b,ld,og='og-dtc.png')
    # 5. back pay
    years=[(2025,'10,138','5,914'),(2024,'9,872','5,758'),(2023,'9,428','5,500'),(2022,'8,870','5,174'),(2021,'8,662','5,053'),(2020,'8,576','5,003'),(2019,'8,416','4,909'),(2018,'8,235','4,804'),(2017,'8,113','4,733'),(2016,'8,001','4,667')]
    b=head('back-pay.html','Back pay: claim up to 10 years.','If your child qualified years ago, you may get money for past years too. Here’s what you can get back, and how far.')
    b+='<div class="sumcard"><div><strong>DTC: up to 10 years</strong><span>If your child qualified in past years and you didn’t claim it, you may be able to claim up to 10 years back. Tick the box on Part A. After approval, CRA fixes your past tax returns for you.</span></div><div><strong>Child Disability Benefit: current + 2 years automatically</strong><span>CRA works out the Child Disability Benefit for this year and the 2 years before, by itself. For years before that, send a letter to your tax centre.</span></div><div><strong>RDSP: catch up 10 years of grants and bonds</strong><span>Grant and bond money you didn’t get in the past 10 years can be paid now (this is called “carry-forward”), if your child had the DTC in those years. When you open a plan, you can get up to $11,000 in bonds. Grants only come when you put money in, and you can get up to $10,500 in grants a year.</span></div></div>'+cite('claiming','cdb','rdspcf','rdsphow')
    b+='<h2>Back-pay checklist</h2><ul class="checklist"><li><label><input type="checkbox"> On Part A, ask CRA to adjust past returns (section 3)</label></li><li><label><input type="checkbox"> Make sure the doctor writes the year the limits started</label></li><li><label><input type="checkbox"> After approval, check CRA’s letter (notice of determination) to see which years are approved</label></li><li><label><input type="checkbox"> If you didn\'t tick the box: use “Change my return” in your CRA account, or mail Form T1-ADJ (the form to change a past tax return) for each year</label></li><li><label><input type="checkbox"> Want to split or move the credit to another family member who supports your child? Send T1-ADJ or a letter</label></li><li><label><input type="checkbox"> Watch for Child Disability Benefit back pay (this year and 2 years back come by themselves). Write to your tax centre for earlier years</label></li><li><label><input type="checkbox"> Open an RDSP and ask the bank to apply for the grant and bond, including money for past years (carry-forward)</label></li><li><label><input type="checkbox"> File every year\'s taxes, even with no income</label></li></ul>'+pr
    b+='<h2>Disability amounts CRA lists for past years</h2><p>The DTC is a non-refundable credit. That means it lowers the tax you owe, but it isn’t paid as cash by itself. If your child has no income, a parent who supports them may be able to use it instead (a transfer). If nobody owed tax that year, you may not get money back for it.</p><table><caption>CRA disability amounts (federal)</caption><thead><tr><th scope="col">Year</th><th scope="col">Disability amount</th><th scope="col">Supplement (under 18)</th></tr></thead><tbody>'+''.join(f'<tr><td>{y}</td><td>${a}</td><td>${s}</td></tr>' for y,a,s in years)+'</tbody></table>'+cite('claiming')
    b+='<h2>Rules to know</h2><ul><li>CRA: “A refund cannot be issued for adjustment request beyond 10 calendar years.”</li><li>You must ask for RDSP grants and bonds by the end of the year the person the RDSP is for turns 49.</li><li>RDSP money for past years can’t go back before 2008, when RDSPs started.</li></ul>'+cite('change','rdspcf')
    b+=share('back-pay.html','If your child qualified for the Disability Tax Credit years ago, you may be able to claim back up to 10 years. Plain-language checklist:')+srcs('claiming','change','cdb','rdspcf','rdsphow','rc4064')
    faq=[("How far back can I claim the Disability Tax Credit?","CRA says if your child qualified in past years and you didn’t claim it, you may be able to claim up to 10 years back."),("Is the Child Disability Benefit paid for past years?","Yes. CRA works it out for this year and the 2 years before, by itself. For years before that, send a letter to your tax centre."),("Can I catch up on RDSP grants and bonds?","Yes. Grant and bond money from the past 10 years can be paid now, if your child had the DTC in those years. When you open a plan, you can get up to $11,000 in bonds. Grants only come when you put money in, up to $10,500 a year.")]
    b+=''.join(f'<h2>{E(a)}</h2><p>{E(c)}</p>' for a,c in faq)
    ld=[{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":a,"acceptedAnswer":{"@type":"Answer","text":c}} for a,c in faq]}]
    page('funding/dtc/back-pay.html','DTC back pay: claim up to 10 years, CDB arrears and RDSP carry-forward','How BC parents can claim Disability Tax Credit back pay for up to 10 years, Child Disability Benefit for past years, and 10 years of RDSP grant and bond carry-forward.',b,ld,og='og-dtc.png')
